      const flyAngle = rnd() * Math.PI * 2;
      const sx = pt.x + Math.cos(flyAngle) * flyDist;
      const sy = pt.y + Math.sin(flyAngle) * flyDist;
      // Speck size -- most are tiny pinpoints
