      const pr=D*(0.12+0.1*c.vmax); const px=cx+Math.cos(c.t*6.2832*1.6-1.2)*D*(0.08+0.4*Math.sqrt(c.t))*0.9, py=cy+Math.sin(c.t*6.2832*1.6-1.2)*D*(0.08+0.4*Math.sqrt(c.t));
