      const _gfMul = _chGf ? (0.68 + 0.76*(0.5*_chGf.energy + 0.5*_chGf.density)) : 1;
      const motifs = Math.max(4, Math.round((cn<=12 ? 5 : cn<=40 ? 8 : 12) * _gfMul));
