// ═══════════════════════════════════════════════════════════════════════════
// HARING LISTENS — the picture the piece asks for: a quick, dense piece the party (two colours split on the slant, the
// scenes all over it, the dog running through, the saucer when it is loud); an even piece the parade along a snake (the
// figures walking and jumping it, a dog with them, on bands); a slow piece the two big figures holding each other on dots,
// the heart over them full of his dashes, a dog sitting by.
// ═══════════════════════════════════════════════════════════════════════════
function haringListen(ctx,CW,CH,chords,lim,gc,sessionSeed,mode){
  const ss=sessionSeed|0, isBW=mode==='bw', cn=chords.length, D=Math.min(CW,CH), reveal=_matReveal(chords,lim);
  const A=_kd2Analyze(chords,gc,mode), X=_hear(chords,A), st=_hgStats(chords,gc,isBW); const dens=A.ch?A.ch.density:0.3;
  const pic = (X.pace>0.62 && dens>0.25) ? 'party' : (X.regular>0.55) ? 'parade' : 'pair';
  const bg=isBW?[236,236,232]:st[0], bg2=_hgOn(st[1]||_HG_PAL[2],bg,isBW); const O=Math.max(2,D*0.009); const Ops=_mtOps(); const used=new Set();
  const colOf=(q,i)=>_hgOn(_hgAt(chords,Math.floor((q.a+q.b)/2),gc,isBW),bg,isBW); const red=_hgOn(_hgPastel(_HG_PAL[0]),bg,isBW);
  if(pic==='party'){ Ops.at(0,()=>_hgBG(ctx,CW,CH,'split',bg,bg2,_HG_BLK,D,66000+ss));
    // a dense piece crowds the party: 4 dancers for a lively one, up to 9 for a torrent of notes (Chopin, the Bumblebee)
    const nF=Math.max(4,Math.min(9,Math.round(1+9*dens))); const G=_kd2Phrases(A,nF+1); const s=D*0.1*(nF>4?Math.sqrt(4/nF)*1.12:1);
    const spots=nF<=4 ? [[0.27,0.3],[0.73,0.27],[0.3,0.66],[0.72,0.64]] : (()=>{ const cols=nF>6?3:2, rows=Math.ceil(nF/cols), o=[]; for(let i=0;i<nF;i++){ const c=i%cols, r=(i/cols)|0; o.push([(c+0.5)/cols+((r%2)?0.04:-0.04), 0.24+0.58*(r+0.5)/rows]); } return o; })();
    G.slice(0,nF).forEach((q,i)=>{ const r=_hgR(66100+i,ss); const h=_mtHearSpan(A,q.a,q.b); let kind=_hgSceneOf(h,used,r); if(kind==='saucer'||kind==='hand') kind='leap'; if(i===2) kind='tv'; const [px,py]=spots[i]; const c=colOf(q,i), c2=_hgOn(st[(i+2)%st.length],bg,isBW);
      Ops.at(q.t0, ()=>_hgScene(ctx,kind,CW*px,CH*py,s*(kind==='lift'||kind==='leap'?0.8:1),66200+i+ss,c,_hgSame(c,c2)?_hgOn(_HG_PAL[(i*3+5)%8],bg,isBW):c2,{ink:_HG_BLK,O,motion:0.5+0.5*X.energy,pat:i%2?'dash':null,red},bg)); });
    const q=G[nF]||G[G.length-1]; Ops.at(q.t0, ()=>_hgRoundDog(ctx,CW*0.5,CH*0.97-1.6*s*0.8,s*0.8,(ss&1)?1:-1,colOf(q,nF),_HG_BLK,O));
    Ops.at(0.5, ()=>_hgSaucer(ctx,CW*0.5,CH*0.08,s*0.5,red,_HG_BLK,O,null)); }
  else if(pic==='parade'){ Ops.at(0,()=>_hgBG(ctx,CW,CH,'hstripes',bg,bg2,_HG_BLK,D,66300+ss)); const sp=[]; for(let i=0;i<=12;i++){ const t=i/12; const e=A.ev[Math.floor(t*(cn-1))]||{top:60}; sp.push([CW*(0.04+0.92*t), CH*(0.58+0.12*(0.5-A.reg(e.top)))+Math.sin(t*8)*CH*0.04]); }
    Ops.at(0.01,()=>_hgSnake(ctx,sp,D*0.075,_hgOn(st[2]||_HG_PAL[1],bg,isBW),_HG_BLK,O,'dash')); const G=_kd2Phrases(A,6); const s=Math.min(CW/9,CH*0.075); Ops.at(0.6,()=>_hgSaucer(ctx,CW*0.78,CH*0.1,s*0.6,_hgOn(_hgPastel(_HG_PAL[0]),bg,isBW),_HG_BLK,O,null));
    G.forEach((q,i)=>{ const r=_hgR(66400+i,ss); const h=_mtHearSpan(A,q.a,q.b); const t=(i+0.5)/G.length; const k=Math.round(t*12); const [x,y]=sp[Math.min(12,k)]; const c=colOf(q,i); const up=i%2===0;
      Ops.at(q.t0, ()=>{ if(i===2) _hgRoundDog(ctx,x,y-s*1.55,s*0.75,1,c,_HG_BLK,O,null,'beg'); else if(i===4) _hgRoundDog(ctx,x,y-s*1.55,s*0.75,1,c,_HG_BLK,O,null,'stand'); else _hgFig(ctx,up?'jump':_hgPoseOf(h,r),x,up?y-s*2.3:y+s*2.4,s,1,0,66500+i+ss,{col:c,ink:_HG_BLK,O,motion:0.5+0.4*X.energy,pat:i%3===1?'dash':null}); }); }); }
  else { Ops.at(0,()=>_hgBG(ctx,CW,CH,'dots',bg,bg2,_HG_BLK,D,66600+ss)); const G=_kd2Phrases(A,3); const s=Math.min(CH*0.13,CW*0.2);
    if(G[0]) Ops.at(G[0].t0, ()=>_hgPair(ctx,X.major?'hug':'back',CW*0.5,CH*0.6,s,66700+ss,colOf(G[0],0),colOf(G[1]||G[0],1),{ink:_HG_BLK,O,motion:0.35}));
    if(X.major && G[1]) Ops.at(G[1].t0, ()=>{ const hy=CH*0.18; _hgHeart(ctx,CW*0.5,hy,s*0.8,red,_HG_BLK,O*1.2); _hgRays(ctx,CW*0.5,hy,s*1.1,s*1.45,9,-Math.PI/2,3.0,_HG_BLK,O*1.2); });
    if(G[2]) Ops.at(G[2].t0, ()=>_hgRoundDog(ctx,CW*0.8,CH*0.97-1.6*s*0.7,s*0.7,-1,colOf(G[2],2),_HG_BLK,O,null,'sit')); }
  Ops.run(reveal); try{ globalThis.__HG_LISTEN={v:'listen',pic}; }catch(_){} _setCurE(0.5);
}

// ═══════════════════════════════════════════════════════════════════════════
// HARING — THE GIANT: one huge figure filled with his dashes over two colours split on the slant, in the pose the whole
// piece asks for, the rays round him at every accent; small figures climbing a ladder to his hand, a dog at his feet, the
// saucer by his head when the piece is loud.
// ═══════════════════════════════════════════════════════════════════════════
function haringGiant(ctx,CW,CH,chords,lim,gc,sessionSeed,mode){
  const ss=sessionSeed|0, isBW=mode==='bw', cn=chords.length, D=Math.min(CW,CH), reveal=_matReveal(chords,lim);
  const A=_kd2Analyze(chords,gc,mode), X=_hear(chords,A), st=_hgStats(chords,gc,isBW); const isAcc=_mtAccOf(A);
  const bg=isBW?[236,236,232]:st[0], bg2=_hgOn(st[1]||_HG_PAL[5],bg,isBW); const O=Math.max(2,D*0.011); const h=_mtHearSpan(A,0,cn);
  const kind= X.energy>0.7 ? (X.leaps>0.5?'jump':'cheer') : X.energy>0.45 ? (X.leaps>0.5?'run':'dance') : (h.reg>0.55?'wave':'reach');
  const s=Math.min(CH*0.17,CW*0.27), gx=CW*0.52, gy=CH*0.5; const big=_hgOn(st[2]||_HG_PAL[1],bg,isBW); const Ops=_mtOps();
  Ops.at(0,()=>_hgBG(ctx,CW,CH,'split',bg,bg2,_HG_BLK,D,67000+ss));
  Ops.at(0.02,()=>_hgFig(ctx,kind,gx,gy,s,(ss&1)?1:-1,0,67100+ss,{col:big,ink:_HG_BLK,O:O*1.3,pat:'dash',hole:X.major?null:bg2,motion:0}));
  const E=_kd2Events(A,40).filter(isAcc); const nR=Math.max(9,Math.min(20,E.length+9));
  for(let k=0;k<nR;k++){ const a=-Math.PI/2+(k/nR-0.5)*Math.PI*1.3; Ops.at((k+0.5)/nR, ()=>{ ctx.strokeStyle=_hgCss(_HG_BLK); ctx.lineWidth=O*1.3; ctx.lineCap='round'; ctx.beginPath(); ctx.moveTo(gx+Math.cos(a)*s*2.1,gy-s*0.5+Math.sin(a)*s*2.1); ctx.lineTo(gx+Math.cos(a)*s*2.45,gy-s*0.5+Math.sin(a)*s*2.45); ctx.stroke(); }); }
  const G=_kd2Phrases(A,4); const sm=s*0.32; const c=(i)=>_hgOn(_hgAt(chords,Math.floor(((G[i]||G[0]).a+(G[i]||G[0]).b)/2),gc,isBW),bg,isBW);
  if(G[0]) Ops.at(G[0].t0, ()=>{ _hgLadder(ctx,CW*0.12,CH*0.95,CH*0.45,D*0.06,_HG_BLK,O); _hgFig(ctx,'reach',CW*0.12,CH*0.66,sm,1,-0.2,67200+ss,{col:c(0),ink:_HG_BLK,O,motion:0.4}); });
  if(G[1]) Ops.at(G[1].t0, ()=>_hgRoundDog(ctx,gx+s*1.2,CH*0.96-1.6*sm*1.3,sm*1.3,-1,_hgOn(c(1),bg2,isBW),_HG_BLK,O));
  if(G[2]) Ops.at(G[2].t0, ()=>_hgFig(ctx,'jump',CW*0.86,CH*0.6,sm,-1,0.15,67201+ss,{col:c(2),ink:_HG_BLK,O,motion:0.6}));
  if(G[3] && X.loud>0.55) Ops.at(G[3].t0, ()=>_hgSaucer(ctx,CW*0.84,CH*0.1,sm*0.9,c(3),_HG_BLK,O,null)); else if(G[3]) Ops.at(G[3].t0, ()=>_hgBolt(ctx,CW*0.85,CH*0.13,sm*1.1,_hgOn(_hgPastel(_HG_PAL[1]),bg,isBW),_HG_BLK,O));
  Ops.run(reveal); try{ globalThis.__HG_LISTEN={v:'giant',kind}; }catch(_){} _setCurE(0.5);
}

// ═══════════════════════════════════════════════════════════════════════════
// HARING — THE SNAKE: one huge snake winding down the whole sheet, drawn by the melody, crossed with his marks; on it and
// round it the figures — riding it, jumping it, running from it — and a dog running with them, a passage each.
// ═══════════════════════════════════════════════════════════════════════════
function haringSnakeWall(ctx,CW,CH,chords,lim,gc,sessionSeed,mode){
  const ss=sessionSeed|0, isBW=mode==='bw', cn=chords.length, D=Math.min(CW,CH), reveal=_matReveal(chords,lim);
  const A=_kd2Analyze(chords,gc,mode), X=_hear(chords,A), st=_hgStats(chords,gc,isBW); const bg=isBW?[236,236,232]:(st[1]||st[0]); const O=Math.max(2,D*0.01);
  const sp=[]; const N=18; for(let i=0;i<=N;i++){ const t=i/N; const e=A.ev[Math.floor(t*(cn-1))]||{top:60}; sp.push([CW*(0.5+(0.3+0.08*(A.reg(e.top)-0.5))*Math.sin(t*Math.PI*3.2)), CH*(0.05+0.9*t)]); }
  const Ops=_mtOps(); const sc=_hgOn(st[0],bg,isBW); Ops.at(0,()=>_hgBG(ctx,CW,CH,'checker',bg,_hgOn(st[3]||_HG_PAL[7],bg,isBW),_HG_BLK,D,68000+ss));
  for(let k=1;k<=N;k++){ Ops.at((k/N)*0.6, ()=>{}); } Ops.at(0.01,()=>_hgSnake(ctx,sp,D*0.11,sc,_HG_BLK,O*1.2,'cross'));
  const G=_kd2Phrases(A,7); const s=D*0.06;
  G.forEach((q,i)=>{ const r=_hgR(68100+i,ss); const h=_mtHearSpan(A,q.a,q.b); const k=Math.min(N,Math.round(((i+0.5)/G.length)*N)); const [x,y]=sp[k]; const side=(x<CW/2)?1:-1; const c=_hgOn(_hgAt(chords,Math.floor((q.a+q.b)/2),gc,isBW),bg,isBW);
    Ops.at(q.t0, ()=>{ if(i===3) _hgRoundDog(ctx,x+side*s*2.6,y,s*0.8,side,c,_HG_BLK,O,null,'stand'); else if(i%3===0) _hgFig(ctx,'dance',x,y-s*1.5,s,1,0,68200+i+ss,{col:c,ink:_HG_BLK,O,motion:0.5});
      else _hgFig(ctx,i%3===1?'jump':_hgPoseOf(h,r),x+side*s*2.4,y,s,side,0,68200+i+ss,{col:c,ink:_HG_BLK,O,motion:0.5+0.4*X.energy,pat:i%2?'dash':null}); }); });
  Ops.run(reveal); try{ globalThis.__HG_LISTEN={v:'snake'}; }catch(_){} _setCurE(0.5);
}
// ═══════════════════════════════════════════════════════════════════════════
// HARING — THE POSTER (the Pop Shop sheet): one flat colour and on it one big figure (two when the piece has two voices,
// dancing at each other), in the pose the whole piece asks for, the rays round him as many as its accents.
// ═══════════════════════════════════════════════════════════════════════════
function haringPoster(ctx,CW,CH,chords,lim,gc,sessionSeed,mode){
  const ss=sessionSeed|0, isBW=mode==='bw', cn=chords.length, D=Math.min(CW,CH), reveal=_matReveal(chords,lim);
  const A=_kd2Analyze(chords,gc,mode), X=_hear(chords,A), st=_hgStats(chords,gc,isBW); const isAcc=_mtAccOf(A);
  const bg=isBW?[232,232,228]:st[0], O=Math.max(2,D*0.013); const two=X.poly>=2.3 || (A.ch?A.ch.density:0.3)>0.6; const h=_mtHearSpan(A,0,cn); const r=_hgR(63000,ss);   // thick chords or a dense piece: the pair
  const kind= X.energy>0.7 ? (X.leaps>0.5?'jump':'cheer') : X.energy>0.45 ? (X.leaps>0.5?'run':'dance') : (h.reg>0.55?'wave':'hold');
  const Ops=_mtOps(); Ops.at(0,()=>_hgGround(ctx,CW,CH,bg,ss));
  const s=two?Math.min(CH*0.14,CW*0.19):Math.min(CH*0.17,CW*0.3); const figs=two?[[CW*0.3,1],[CW*0.7,-1]]:[[CW*0.5,r()<0.5?1:-1]]; const fy=CH*0.52;
  figs.forEach(([fx,dir],i)=>{ const col=_hgOn(st[1+i]||_hgPastel(_HG_PAL[(i*3+2)%8]),bg,isBW); const k2=two&&i===1?(kind==='hold'?'wave':kind==='jump'?'dance':kind):kind;
    Ops.at(i*0.12, ()=>_hgPut(ctx,k2,fx,fy,s,dir,0,col,_HG_BLK,O,63100+i+ss,0)); });
  // the rays: one ring of dashes round each figure, a dash per accent as the piece reaches it
  const E=_kd2Events(A,40).filter(isAcc); const nR=Math.max(8,Math.min(22,E.length+8));
  figs.forEach(([fx],i)=>{ for(let k=0;k<nR;k++){ const t=(k+0.5)/nR; const a=-Math.PI/2+(k/nR)*6.2832*(two?0.5:1)-(two?Math.PI*0.5:0)+(two&&i?Math.PI:0); const cx=fx, cy=fy-s*0.4; const R0=s*1.85, R1=s*(2.1+0.25*X.energy);
    Ops.at(t, ()=>{ ctx.strokeStyle=_hgCss(_HG_BLK); ctx.lineWidth=O*1.25; ctx.lineCap='round'; ctx.beginPath(); ctx.moveTo(cx+Math.cos(a)*R0,cy+Math.sin(a)*R0*1.08); ctx.lineTo(cx+Math.cos(a)*R1,cy+Math.sin(a)*R1*1.08); ctx.stroke(); }); } });
  // the little marks of motion off the hands and feet, quicker pieces more
  figs.forEach(([fx,dir],i)=>{ Ops.at(0.5+i*0.1, ()=>{ const F=_hgFigure(fx,fy+0.25*s,s,two&&i===1?(kind==='hold'?'wave':kind==='jump'?'dance':kind):kind,dir,_hgR(63100+i+ss,3),1); _hgMotion(ctx,F,_HG_BLK,O*1.1,0.3+0.6*X.pace,_hgR(63200+i,ss)); }); });
  Ops.run(reveal); try{ globalThis.__HG_LISTEN={v:'poster',kind,two}; }catch(_){} _setCurE(0.5);
}


// ═══════════════════════════════════════════════════════════════════════════
// HARING — THE SUBWAY (the chalk drawings on the black paper of the empty ad panels, 1980–85): drawn fast and big, the
// chalk line only, the inside the black of the paper. A few large figures fill the panel — a passage each, in the pose it
// asks for — the loudest one with its rays and, when the piece is major, the heart over him; the dashes of motion; the
// chalk never quite solid. (colour: the same in coloured chalk, every figure its passage's colour)
// ═══════════════════════════════════════════════════════════════════════════
function _haringChalk(ctx,CW,CH,chords,lim,gc,sessionSeed,mode,colour){
  const ss=sessionSeed|0, isBW=mode==='bw', cn=chords.length, D=Math.min(CW,CH), reveal=_matReveal(chords,lim);
  const A=_kd2Analyze(chords,gc,mode), X=_hear(chords,A); const chalk=[244,242,234], paper=[22,21,24];
  const fm=D*0.028, x0=fm, y0=fm, W=CW-2*fm, H=CH-2*fm; const land=CW>CH*1.1;
  const n=Math.max(3,Math.min(5,Math.round(2.5+X.pace*2+(X.poly>2.4?1:0)))); const G=_kd2Phrases(A,n); const m=G.length; let ci=0; G.forEach((q,i)=>{ if(q.vmax>G[ci].vmax) ci=i; });
  const rowsN=land?1:(m>3?2:1), per=Math.ceil(m/rowsN); const rowH=H/rowsN; const s=Math.min(W*0.92/(per*2.45), rowH/4.4); const O=Math.max(1.6,s*0.075);
  const Ops=_mtOps(); Ops.at(0,()=>{ ctx.fillStyle='rgb(120,116,110)'; ctx.fillRect(0,0,CW,CH); ctx.fillStyle=_hgCss(paper); ctx.fillRect(x0,y0,W,H);
    const r=_hgR(64001,ss); for(let i=0;i<5;i++){ const cx=x0+r()*W, cy=y0+r()*H, R=D*(0.25+0.3*r()); const g=ctx.createRadialGradient(cx,cy,0,cx,cy,R); g.addColorStop(0,'rgba(255,255,255,0.035)'); g.addColorStop(1,'rgba(255,255,255,0)'); ctx.fillStyle=g; ctx.fillRect(x0,y0,W,H); } });
  G.forEach((q,i)=>{ const row=Math.floor(i/per), j=i%per, inRow=Math.min(per,m-row*per); const r=_hgR(64100+i,ss); const h=_mtHearSpan(A,q.a,q.b); let kind=_hgPoseOf(h,r); if(kind==='kneel') kind='dance';
    const fx=x0+W*(0.5+(j-(inRow-1)/2)/Math.max(1,per)*0.94)+(r()-.5)*s*0.3, fy=y0+rowH*row+rowH*0.5-2.05*s+2.55*s+(r()-.5)*s*0.15, dir=(j%2?-1:1)*(r()<0.8?1:-1);
    const tint=isBW?chalk:_hgPalOf(_picChord(chords,Math.floor((q.a+q.b)/2),gc,false).rgb,false).map(v=>Math.round(v+(255-v)*0.35)); const ink=colour===true?tint:chalk, acc=colour?tint:chalk;
    const rot=(r()-.5)*0.12, mo=0.45+0.5*X.energy;
    const isDog= i===1 && m>=4 && i!==ci;
    Ops.at(q.t0, ()=>{ const big=i===ci, sz=s*(big?1.08:1); if(isDog){ _hgRoundDog(ctx,fx,fy,sz*0.95,dir,null,ink,O,paper); return; } const F=_hgPut(ctx,kind,fx,fy,sz,dir,rot,null,ink,O,64200+i+ss,colour==='accent'?0:mo,paper);
      if(colour==='accent'){ ctx.save(); ctx.translate(fx,fy); ctx.rotate(rot); _hgMotion(ctx,F,acc,Math.max(1.4,sz*0.085),mo,_hgR(64200+i+ss,4)); ctx.restore(); }
      if(big){ _hgRays(ctx,fx,fy-s*0.9,s*1.25,s*(1.5+0.15*X.energy),11,-Math.PI/2,3.3,acc,O*1.2); }
      if(big && X.major){ const hx=fx-dir*s*1.45, hy=fy-s*1.95; const P=_hgHeartPts(hx,hy,s*0.34); ctx.beginPath(); P.forEach((p,k)=>k?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1])); ctx.closePath(); ctx.strokeStyle=_hgCss(colour?[240,96,110]:ink); ctx.lineWidth=O*1.4; ctx.lineJoin='round'; ctx.stroke(); } }); });
  // the ground he drew them standing on, one quick line per row
  for(let row=0;row<rowsN;row++){ const by=y0+rowH*row+rowH*0.5+0.5*s+1.65*s; const q0=G[row*per]; const t=q0?q0.t0:0; const lc=(colour==='accent'&&q0&&!isBW)?_hgPalOf(_picChord(chords,Math.floor((q0.a+q0.b)/2),gc,false).rgb,false).map(v=>Math.round(v+(255-v)*0.35)):chalk; Ops.at(t, ()=>{ ctx.strokeStyle=_hgCss(lc,0.85); ctx.lineWidth=O*1.1; ctx.lineCap='round'; ctx.beginPath(); ctx.moveTo(x0+W*0.05,by); ctx.lineTo(x0+W*0.95,by); ctx.stroke(); }); }
  Ops.run(reveal);
  // the chalk: the line never quite solid, a little dust on the paper
  const r=_hgR(64900,ss); ctx.fillStyle=_hgCss(paper,0.55); const k=Math.round(W*H/520); for(let i=0;i<k;i++){ ctx.fillRect(x0+r()*W,y0+r()*H,0.8+r()*1.6,0.8+r()*1.6); }
  ctx.fillStyle='rgba(255,255,255,0.05)'; for(let i=0;i<k/6;i++){ ctx.fillRect(x0+r()*W,y0+r()*H,1+r()*2,1); }
  try{ globalThis.__HG_LISTEN={v:colour==='accent'?'subwayA':colour?'subwayC':'subway',n:m,rowsN}; }catch(_){} _setCurE(0.5);
}
function haringSubwayChalk(ctx,CW,CH,chords,lim,gc,ss,mode){ _haringChalk(ctx,CW,CH,chords,lim,gc,ss,mode,true); }
function haringSubwayAccent(ctx,CW,CH,chords,lim,gc,ss,mode){ _haringChalk(ctx,CW,CH,chords,lim,gc,ss,mode,'accent'); }

// ── Pop (Keith Haring) ───────────────────────────────────────────────────────
// Bold flat colour blocks behind thick black-outlined glyphs, with radiating
// "energy" ticks around them (Keith Haring's street-pop language). Each cell
// is a colour from a chord via gc(); a simple glyph (figure, heart, star,
// spiral, burst) sits on top with a heavy black contour and motion dashes.
// ── Haring cast engine ───────────────────────────────────────────────────────
// The outlined creature as a primitive: chunky limbs drawn twice (a thick black
// stroke, then the colour inside it), round heads, motion dashes. A cast of
// different creatures — dancer, runner, jumper, waver, two figures holding up
// a heart — so a wall never repeats one
// figure. Slot 0 is the app's mosaic in Haring's hand (one tile per chord);
// slot 3 the all-over doodle with a few characters caught in it.
const _hrR=(a,ss)=>_seedRnd(a,ss,0,0);
const _hrClamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const _hrCss=(c)=>`rgb(${c[0]|0},${c[1]|0},${c[2]|0})`;
const _HR_BLK=[18,16,18];
function _hrFlat(rgb,isBW){ if(isBW){ const l=rgb[0]*0.299+rgb[1]*0.587+rgb[2]*0.114; return [l,l,l]; } const g=(rgb[0]+rgb[1]+rgb[2])/3; const c=rgb.map(v=>_hrClamp(g+(v-g)*1.8,0,255)); const m=Math.max(c[0],c[1],c[2])||1; return c.map(v=>_hrClamp(v*Math.min(1.4,240/m),0,255)); }
function _hrSetup(chords,gc,mode){ const isBW=mode==='bw'; const cn=chords.length; const ch=(typeof computeSongCharacter==='function')?computeSongCharacter(chords):null;
  return {cn,isBW,energy:ch?ch.energy:0.5,density:ch?ch.density:0.4,col:(t)=>_hrFlat(_picChord(chords,_hrClamp(Math.floor(t*cn),0,cn-1),gc,isBW).rgb,isBW)}; }
// ── the cast: each returns {lines:[{p:[[x,y]..],w}], heads:[[x,y,r]], fills:[[pts]], glow:[cx,cy,r0,r1,n,a0,span]}
const _hrO=(x,y,dir)=>(dx,dy)=>[x+dx*dir,y+dy];
function _hrDancer(x,y,u,r,e,dir){ const p=_hrO(x,y,dir); const up=0.5+e*0.5; const neck=p(0,-2.4*u), hips=p(0,0);
  return {lines:[{p:[neck,hips]},{p:[neck,p(-1.3*u,-2.4*u-1.0*u*up),p(-1.6*u-r()*0.6*u,-2.4*u-2.2*u*up)]},{p:[neck,p(1.3*u,-2.4*u-(0.2+r()*0.9)*u),p(2.3*u,-2.4*u-(r()*1.6)*u)]},{p:[hips,p(-0.9*u,1.3*u),p(-1.5*u,2.6*u)]},{p:[hips,p(1.0*u,1.2*u),p(0.9*u,2.7*u)]}],heads:[[...p(0,-3.6*u),u]],glow:[...p(0,-3.6*u),1.8*u,2.6*u,3,-1.57,1.2]}; }
function _hrRunner(x,y,u,r,e,dir){ const p=_hrO(x,y,dir); const neck=p(0.8*u,-2.3*u), hips=p(0,0);
  return {lines:[{p:[neck,hips]},{p:[neck,p(2.0*u,-2.6*u),p(2.9*u,-3.6*u)]},{p:[neck,p(-0.4*u,-1.5*u),p(-1.5*u,-2.0*u)]},{p:[hips,p(1.5*u,0.9*u),p(1.4*u,2.6*u)]},{p:[hips,p(-0.9*u,1.4*u),p(-2.3*u,1.8*u)]}],heads:[[...p(1.4*u,-3.4*u),u]],glow:[...p(-1.2*u,-1.2*u),2.2*u,3.2*u,4,dir>0?3.14:0,1.0]}; }
function _hrJumper(x,y,u,r,e,dir){ const p=_hrO(x,y,dir); const neck=p(0,-2.4*u), hips=p(0,0);
  return {lines:[{p:[neck,hips]},{p:[neck,p(-1.5*u,-3.1*u),p(-2.6*u,-4.1*u)]},{p:[neck,p(1.5*u,-3.1*u),p(2.6*u,-4.1*u)]},{p:[hips,p(-1.2*u,0.8*u),p(-1.0*u,2.3*u)]},{p:[hips,p(1.3*u,0.5*u),p(2.1*u,1.5*u)]}],heads:[[...p(0,-3.6*u),u]],glow:[...p(0,2.6*u),0.6*u,1.4*u,5,1.57,2.0]}; }
function _hrWaver(x,y,u,r,e,dir){ const p=_hrO(x,y,dir); const neck=p(0,-2.4*u), hips=p(0,0);
  return {lines:[{p:[neck,hips]},{p:[neck,p(1.2*u,-3.0*u),p(1.5*u,-4.4*u)]},{p:[neck,p(-1.1*u,-1.6*u),p(-1.4*u,-0.4*u)]},{p:[hips,p(-0.6*u,1.4*u),p(-0.7*u,2.7*u)]},{p:[hips,p(0.6*u,1.4*u),p(0.7*u,2.7*u)]}],heads:[[...p(0,-3.6*u),u]],glow:[...p(1.5*u,-4.6*u),0.8*u,1.6*u,3,-1.2*dir,1.4]}; }
function _hrHeart(cx,cy,h){ const pts=[]; for(let i=0;i<=40;i++){ const t=i/40*6.2832; const x=16*Math.pow(Math.sin(t),3), y=-(13*Math.cos(t)-5*Math.cos(2*t)-2*Math.cos(3*t)-Math.cos(4*t)); pts.push([cx+x*h/17,cy+y*h/17]); } return pts; }
function _hrPairHeart(x,y,u,r,e,dir){ const a=_hrO(x-2.4*u,y,1), b=_hrO(x+2.4*u,y,1); const na=a(0,-2.4*u), nb=b(0,-2.4*u);
  return {lines:[{p:[na,a(0,0)]},{p:[na,a(0.9*u,-3.6*u),a(1.8*u,-4.9*u)]},{p:[na,a(-1.2*u,-1.6*u),a(-1.6*u,-0.4*u)]},{p:[a(0,0),a(-0.7*u,1.4*u),a(-0.8*u,2.7*u)]},{p:[a(0,0),a(0.6*u,1.4*u),a(0.7*u,2.7*u)]},
                 {p:[nb,b(0,0)]},{p:[nb,b(-0.9*u,-3.6*u),b(-1.8*u,-4.9*u)]},{p:[nb,b(1.2*u,-1.6*u),b(1.6*u,-0.4*u)]},{p:[b(0,0),b(-0.6*u,1.4*u),b(-0.7*u,2.7*u)]},{p:[b(0,0),b(0.7*u,1.4*u),b(0.8*u,2.7*u)]}],
          heads:[[...a(-0.4*u,-3.6*u),u],[...b(0.4*u,-3.6*u),u]],fills:[_hrHeart(x,y-6.4*u,2.2*u)],glow:[x,y-6.4*u,3.0*u,4.0*u,9,-1.57,3.4]}; }
// our round dog (the Mosaic's own): a round body on legs drawn together, the head and the tail up, the mouth shut — it never barks
function _hrRoundDog(x,y,u,r,e,dir){ const p=_hrO(x,y,dir);
  return {lines:[{p:[p(-1.8*u,0),p(1.4*u,0)],w:1.6},{p:[p(-1.5*u,0),p(-1.6*u,2.2*u)]},{p:[p(-0.7*u,0),p(-0.6*u,2.2*u)]},{p:[p(0.5*u,0),p(0.6*u,2.2*u)]},{p:[p(1.2*u,0),p(1.4*u,2.2*u)]},{p:[p(-1.8*u,0),p(-2.6*u,-1.4*u)]},{p:[p(1.4*u,-0.2*u),p(2.2*u,-1.5*u)],w:1.2},{p:[p(2.0*u,-1.6*u),p(3.4*u,-1.3*u)],w:1.5},{p:[p(1.8*u,-2.0*u),p(1.6*u,-2.9*u)],w:0.8}],heads:[],glow:null}; }
const _HR_CAST={dancer:_hrDancer,runner:_hrRunner,jumper:_hrJumper,waver:_hrWaver,pairHeart:_hrPairHeart,rdog:_hrRoundDog};
function _hrCreature(ctx,c,col,u,rnd,glow){ const W=u*1.15, Ol=u*0.4; ctx.lineCap='round'; ctx.lineJoin='round';
  const path=(pts)=>{ ctx.beginPath(); ctx.moveTo(pts[0][0],pts[0][1]); for(let i=1;i<pts.length;i++) ctx.lineTo(pts[i][0],pts[i][1]); };
  ctx.strokeStyle=_hrCss(_HR_BLK); c.lines.forEach(l=>{ ctx.lineWidth=W*(l.w||1)+Ol*2; path(l.p); ctx.stroke(); });
  ctx.fillStyle=_hrCss(_HR_BLK); c.heads.forEach(h=>{ ctx.beginPath(); ctx.arc(h[0],h[1],h[2]+Ol,0,6.2832); ctx.fill(); });
  (c.fills||[]).forEach(f=>{ path(f); ctx.closePath(); ctx.lineWidth=Ol*2; ctx.stroke(); });
  ctx.strokeStyle=_hrCss(col); c.lines.forEach(l=>{ ctx.lineWidth=W*(l.w||1); path(l.p); ctx.stroke(); });
  ctx.fillStyle=_hrCss(col); c.heads.forEach(h=>{ ctx.beginPath(); ctx.arc(h[0],h[1],h[2],0,6.2832); ctx.fill(); });
  (c.fills||[]).forEach(f=>{ ctx.fillStyle=_hrCss(glow||[226,36,40]); path(f); ctx.closePath(); ctx.fill(); });
  if(c.glow){ const [gx,gy,r0,r1,n,a0,span]=c.glow; ctx.strokeStyle=_hrCss(_HR_BLK); ctx.lineWidth=u*0.36; for(let i=0;i<n;i++){ const a=a0+(span>=6.2?i/n:(i/(n-1||1)-0.5))*span+(rnd()-.5)*0.12; ctx.beginPath(); ctx.moveTo(gx+Math.cos(a)*r0,gy+Math.sin(a)*r0); ctx.lineTo(gx+Math.cos(a)*r1,gy+Math.sin(a)*r1); ctx.stroke(); } }
}
const _hrFar=(c,bg)=>{ if(Math.abs(c[0]-bg[0])+Math.abs(c[1]-bg[1])+Math.abs(c[2]-bg[2])<120) return [255-c[0],255-c[1],255-c[2]]; return c; };

// ═══════════════════════════════════════════════════════════════════════════
// HARING LISTENS — not one of the murals above: a picture built from what the
// piece does, with everything that is his — the flat ground, the black line,
// the cast, the radiant marks, the heart, the snake, the flying saucer and its
// beam, the ladder, the motion dashes, the dashes and crosses that fill a body.
//   the ground       the piece's own colour pushed flat; black when it is heavy and minor
//   the picture      CHAIN — figures holding hands along the melody's own contour, one per passage, each in the pose
//                    the passage calls for (runner when it leaps, jumper when it is loud, waver when it repeats,
//                    dancer otherwise) — the line of the melody made of people (slow and medium pieces) · TOTEM —
//                    figures standing on each other's shoulders, one per voice, the loudest on top (many voices) ·
//                    SAUCER — the flying saucer over the crowd, its beam on the figure at the climax, the others
//                    thrown back with radiant marks (loud, quick) · SNAKE — a long snake winding across the sheet
//                    with the figures riding and fleeing it (minor)
//   the signs        a heart over the climax when the piece is major · radiant marks as many as the accents · motion
//                    dashes behind the figures as quick as the piece is · a ladder when it climbs · the big figures
//                    filled with his dashes and crosses when the piece is loud
// ═══════════════════════════════════════════════════════════════════════════
function _hrLinker(x,y,u,r,e,dir){ const p=_hrO(x,y,dir); const neck=p(0,-2.4*u), hips=p(0,0); const lift=0.6*e;
  return {lines:[{p:[neck,hips]},{p:[neck,p(-1.4*u,-2.4*u-lift*u),p(-2.4*u,-2.6*u-lift*u)]},{p:[neck,p(1.4*u,-2.4*u-lift*u),p(2.4*u,-2.6*u-lift*u)]},{p:[hips,p(-0.9*u,1.3*u),p(-1.2*u,2.6*u)]},{p:[hips,p(0.9*u,1.3*u),p(1.2*u,2.6*u)]}],heads:[[...p(0,-3.6*u),u]],glow:null}; }
function _hrStander(x,y,u,r,e,dir){ const p=_hrO(x,y,dir); const neck=p(0,-2.4*u), hips=p(0,0);
  return {lines:[{p:[neck,hips]},{p:[neck,p(-1.6*u,-3.2*u),p(-2.0*u,-4.6*u)]},{p:[neck,p(1.6*u,-3.2*u),p(2.0*u,-4.6*u)]},{p:[hips,p(-1.1*u,1.3*u),p(-1.4*u,2.6*u)]},{p:[hips,p(1.1*u,1.3*u),p(1.4*u,2.6*u)]}],heads:[[...p(0,-3.6*u),u]],glow:null}; }
function _hrFaller(x,y,u,r,e,dir){ const p=_hrO(x,y,dir); const neck=p(-1.6*u,-1.6*u), hips=p(0,0);
  return {lines:[{p:[neck,hips]},{p:[neck,p(-2.4*u,-3.0*u),p(-2.0*u,-4.2*u)]},{p:[neck,p(-0.4*u,-2.8*u),p(0.4*u,-3.8*u)]},{p:[hips,p(1.2*u,0.9*u),p(2.4*u,0.2*u)]},{p:[hips,p(0.6*u,1.6*u),p(1.8*u,2.4*u)]}],heads:[[...p(-2.4*u,-2.4*u),u]],glow:[...p(-2.4*u,-2.4*u),1.8*u,2.8*u,5,-2.4*dir,2.2]}; }
