const _monR=(a,ss)=>_seedRnd(a,ss,0,0);
const _monClamp=(v,a,b)=>Math.max(a,Math.min(b,v)); const _MON_DN=1.0;    // dab density — loaded touches are broader, fewer of them cover the canvas
