  for(let k=0;k<=K;k++){ const u=k/K,q=u-0.5,arc=bend*(1-4*q*q); _MON_PX[k]=x+ca*q*L-sa*arc; _MON_PY[k]=y+sa*q*L+ca*arc; _MON_PW[k]=w*(1-dry*u)*(0.86+rnd()*0.28); }
