      for(let j=0;j<n;j++){ const cc=_monBrk(_monMix(col(ci+j*3),[64,132,72],isBW?0:0.5),(j%2?1:-1),0.1+r()*0.15,isBW); dab(CW*(cx+(r()-.5)*0.22),CH*(cy+(r()-.5)*0.1),D*(0.03+r()*0.02),D*(0.022+r()*0.012),(r()-.5)*0.3,cc,0.92,k/K+r()*0.3,true); }
