      ctx.fillStyle=css(mix(sumi,[90,60,40],0.35),0.6); _wv2Path(ctx,CP.map((p,i)=>[p[0],p[1]+H*0.07+H*0.02*Math.sin(i*2.1)]),false,4); ctx.lineTo(W*1.04,H*1.02); ctx.lineTo(-W*0.04,H*1.02); ctx.closePath(); ctx.fill();
