    voice: (i)=>{ const ch=chords[Math.min(cn-1,Math.max(0,i%cn))]; const nn=(ch&&(ch.n||ch.notes))||[]; const n0=nn.length?nn[0]:{m:60}; const m=n0.m!==undefined?n0.m:n0; return inkFrom(m, 0.50, 0.52); },
